const itens = $input.all();

return itens.map(item => {
  const x = item.json;

  const percentual = Number(x.credit_percent ?? 0);
  const usados = Number(x.credit_used ?? 0);
  const limite = Number(x.credit_limit ?? 0);

  let status = 'NORMAL';
  let permitePublicacao = true;
  let permiteMigracao = true;
  let prioridade = 1;

  if (percentual >= 95) {
    status = 'BLOQUEADA';
    permitePublicacao = false;
    permiteMigracao = false;
    prioridade = 5;

  } else if (percentual >= 90) {
    status = 'CRITICA';
    permitePublicacao = true;
    permiteMigracao = false;
    prioridade = 4;

  } else if (percentual >= 85) {
    status = 'RESTRITA';
    permitePublicacao = true;
    permiteMigracao = false;
    prioridade = 3;

  } else if (percentual >= 70) {
    status = 'ATENCAO';
    permitePublicacao = true;
    permiteMigracao = true;
    prioridade = 2;
  }

  const creditoDisponivel = Math.max(
    limite - usados,
    0
  );

  return {
    json: {
      ...x,

      credit_available:
        Number(creditoDisponivel.toFixed(4)),

      status_operacional:
        status,

      permite_publicacao:
        permitePublicacao ? 1 : 0,

      permite_migracao:
        permiteMigracao ? 1 : 0,

      prioridade_operacional:
        prioridade
    }
  };
});

const x = $json;

if (!x.api_id || !x.cloud_name || !x.api_key || !x.api_secret) {
  throw new Error(
    `Conta Cloudinary incompleta. api_id=${x.api_id}, cloud_name=${x.cloud_name}`
  );
}

const auth = Buffer
  .from(`${x.api_key}:${x.api_secret}`)
  .toString('base64');

return [{
  json: {
    ...x,
    authorization: `Basic ${auth}`
  }
}];

const itens = $input.all();

return itens.map(item => {
  const r = item.json;

  const body =
    r.body && typeof r.body === 'object'
      ? r.body
      : {};

  // Compatível com chamada direta e futura chamada via Worker
  const httpStatus = Number(
    body.origin_status ??
    r.statusCode ??
    0
  );

  const credits = body.credits;

  const apiId = Number(r.api_id);
  const cloudName = r.cloud_name ?? null;

  // --------------------------------------------------
  // Valida estrutura mínima necessária
  // --------------------------------------------------

  const temCredits =
    credits &&
    typeof credits === 'object';

  const temUsage =
    temCredits &&
    Number.isFinite(Number(credits.usage));

  const temLimit =
    temCredits &&
    Number.isFinite(Number(credits.limit));

  const temPercent =
    temCredits &&
    Number.isFinite(Number(credits.used_percent));

  const httpOk =
    httpStatus === 200;

  const usageValido =
    httpOk &&
    temUsage &&
    temLimit &&
    temPercent;

  // --------------------------------------------------
  // Motivo da falha, se houver
  // --------------------------------------------------

  let motivoErro = null;

  if (!httpOk) {
    motivoErro =
      `HTTP_${httpStatus || 'DESCONHECIDO'}`;
  } else if (!temCredits) {
    motivoErro =
      'CREDITS_NAO_ENCONTRADO';
  } else if (!temUsage) {
    motivoErro =
      'CREDIT_USAGE_INVALIDO';
  } else if (!temLimit) {
    motivoErro =
      'CREDIT_LIMIT_INVALIDO';
  } else if (!temPercent) {
    motivoErro =
      'CREDIT_PERCENT_INVALIDO';
  }

  return {
    json: {
      ...r,

      api_id: apiId,
      cloud_name: cloudName,

      http_status_usage:
        httpStatus,

      usage_valido:
        usageValido,

      erro_consulta_usage:
        motivoErro
    }
  };
});

const r = $json;

const apiId = Number(r.api_id);

if (!apiId) {
  throw new Error('api_id inválido na falha de Usage Cloudinary');
}

const httpStatus = Number(
  r.http_status_usage ??
  r.body?.origin_status ??
  r.statusCode ??
  0
);

return [{
  json: {
    api_id: apiId,
    cloud_name: r.cloud_name ?? null,
    account_email: r.account_email ?? null,

    http_status: httpStatus || 0,

    erro_consulta_usage:
      r.erro_consulta_usage ??
      `FALHA_USAGE_HTTP_${httpStatus || 'DESCONHECIDO'}`
  }
}];
